height_probs <- function(mu = 180, var_val = 49) {
  sigma <- sqrt(var_val)
  list(
    p_over_200 = 1 - pnorm(200, mean = mu, sd = sigma),
    p_175_180 = pnorm(180, mean = mu, sd = sigma) - pnorm(175, mean = mu, sd = sigma),
    q10 = qnorm(0.10, mean = mu, sd = sigma)
  )
}

