bayes_posterior <- function(prior, sens, fpr) {
  num <- sens * prior
  num / (num + fpr * (1 - prior))
}

binom_at_least <- function(k, n, p) {
  if (k <= 0) return(1)
  1 - pbinom(k - 1, size = n, prob = p)
}

