questions.solution_code:
run_ttest_summary <- function(x, mu0 = 0, conf_level = 0.95) {
  tt <- t.test(x, mu = mu0, conf.level = conf_level)
  list(
    t_stat = unname(as.numeric(tt$statistic)),
    p_value = as.numeric(tt$p.value),
    ci_low = as.numeric(tt$conf.int[1]),
    ci_high = as.numeric(tt$conf.int[2])
  )
}

